using namespace std;
long long int min_num, min_den;
long long int a_best, b_best;
long long int compute_gcd(long long int a, long long int b)
{
    while (b != 0) {
        long long int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
// Evaluate candidate ratio
void evaluate_ratio(long long int x, long long int y, long long int b, long long int a)
{
    if (a < 0) return;
    long long int g = compute_gcd(a, b);
    a /= g;
    b /= g;
    long long int numerator = abs(b * x - a * y);
    long long int denominator = b * y;
    long long int g2 = compute_gcd(numerator, denominator);
    numerator /= g2;
    denominator /= g2;
    if (numerator * min_den < min_num * denominator) {
        min_num = numerator;
        min_den = denominator;
        a_best = a;
        b_best = b;
        return;
    }
    if (numerator * min_den == denominator * min_num) {
        if (b < b_best) {
            a_best = a;
            b_best = b;
            return;
        }
        if (b > b_best) {
            return;
        }
        if (a < a_best) {
            a_best = a;
            b_best = b;
            return;
        }
    }
}
int main()
{
